set -x; uv run --no-project --python 3.13 python - <<'PY'
import re, sys, pathlib
ROOT = pathlib.Path("ios/BooksAndVocab")
COMMON = [r"\.settingsCard\s*\(", r"\bAppSectionCard\s*\(", r"\.appSettingsButtonChrome\s*\("]
CONTAINER = r"(?<![A-Za-z0-9_])(Form|List)\s*\{"
SECTION = r"(?<![A-Za-z0-9_])Section\s*[({]"
SCREENS = {
 "review-tempo": {
   "anchor": r"(?:struct|extension)\s+SettingsReviewSection\w*\b",
   "ban": COMMON + [r"\bSettingsSelectionTile\s*\(", r"\bSettingsDivider\s*\(",
                    r"\bAppSettingsDivider\s*\("],
   "need": [CONTAINER, SECTION, r"(?<![A-Za-z0-9_])Stepper\s*\(",
            r"(?<![A-Za-z0-9_])Picker\s*\("],
 },
 "card-layout": {
   "anchor": r"(?:struct|extension)\s+ReviewCardLayoutEditor\w*\b",
   "ban": COMMON + [r"\bSettingsDivider\s*\(", r"\bAppSettingsDivider\s*\("],
   "need": [CONTAINER, SECTION],
 },
 "reader-settings": {
   "anchor": r"(?:struct|extension)\s+ReaderSettings(?:Presenter|Panel)\w*\b",
   "ban": COMMON + [r"\bAppAirDivider\s*\(", r"\bReaderSelectionTile\s*\(",
                    r"\bAppSectionBlock\s*\(", r"\bVocabChromeSurface\s*\(",
                    r"\bVocabCard\s*\(", r"\bshowsDragHandle\b"],
   "need": [CONTAINER, SECTION, r"(?<![A-Za-z0-9_])Picker\s*\("],
 },
}
GONE = [r"\bSettingsStepperIconButton\w*", r"\bReaderStepControlButton\w*",
        r"\bvocabControlSurface\w*", r"\bvocabLabelChip\w*",
        r"\bvocabSettingsSection\w*", r"\bvocabHeaderBlock\w*"]
def strip_comments(src):
    src = re.sub(r"/\*.*?\*/", " ", src, flags=re.S)
    return "\n".join(re.sub(r"//.*$", "", ln) for ln in src.split("\n"))
def hits(t, p): return len(re.findall(p, t))
def structural(msg):
    print("STRUCTURAL: " + msg); sys.exit(2)
probe = "let a = b.settingsCard()\n// c.settingsCard() note\nForm {\nSection(header: x) {\n"
st = strip_comments(probe)
if hits(st, COMMON[0]) != 1: structural("ban matcher broken")
if hits(st, CONTAINER) != 1: structural("container matcher broken")
if hits(st, SECTION) != 1: structural("section matcher broken")
if hits(strip_comments("// AppAirDivider()\n"), r"\bAppAirDivider\s*\(") != 0:
    structural("comment stripper broken")
for bad in ("SettingsSectionHeader(", "AppSectionBlock(", "AppSectionCard("):
    if hits(bad, SECTION): structural("section matcher matches " + bad)
if hits("SettingsStepperIconButton(", r"(?<![A-Za-z0-9_])Stepper\s*\("):
    structural("stepper matcher matches SettingsStepperIconButton(")
if not hits("extension SettingsReviewSection {", SCREENS["review-tempo"]["anchor"]):
    structural("anchor matcher cannot see an extension of the seed type")
files = sorted(ROOT.rglob("*.swift"))
if len(files) < 300: structural("only %d swift files visible; wrong cwd?" % len(files))
code = {p: strip_comments(p.read_text(encoding="utf-8")) for p in files}
fail = []
for key, spec in SCREENS.items():
    group = [p for p in files if hits(code[p], spec["anchor"])]
    if not group:
        structural("no file declares the %s type; renamed or deleted?" % key)
    blob = "\n".join(code[p] for p in group)
    for p in group:
        for pat in spec["ban"]:
            n = hits(code[p], pat)
            if n: fail.append("%s [%s]: %d hand-drawn call site(s) of /%s/" % (p, key, n, pat))
    for pat in spec["need"]:
        if hits(blob, pat) < 1:
            fail.append("%s: no native construct matching /%s/ anywhere in its %d file(s)"
                        % (key, pat, len(group)))
for pat in GONE:
    where = ["%s x%d" % (p, hits(code[p], pat)) for p in files if hits(code[p], pat)]
    if where: fail.append("/%s/ still exists in the tree: %s" % (pat, ", ".join(where)))
if fail:
    print("\n".join(fail)); sys.exit(1)
print("OK: the 3 settings screens are native-first")
PY
